/**
 * T021/004-compliance-management — `CreateFrameworkUseCase`
 * (`POST /frameworks`, `createFramework` operation, FR-001, FR-002,
 * FR-023). Mirrors `modules/controls/application/create-control.usecase.ts`'s
 * structure — see that file's header for the transaction-boundary
 * reasoning this one does not repeat. No organizational scope anywhere
 * (research.md D-2): unlike `CreateControlUseCase`, there is no
 * `orgUnitId` to validate.
 *
 * `code` is generated by the shared allocator
 * (`EntityCodeGeneratorPort.nextCode('FMK', year)`, `GrcCodeSequence`, the
 * SAME allocator Evidence/Action/Finding/Control already use, extended
 * with the `FMK` prefix at T019) — never a second, duplicated counter
 * mechanism in this module (research.md D-14).
 *
 * A framework is created with no versions — legible, with no compliance
 * state to report until it has at least one PUBLISHED version (edge case
 * "framework sem versão alguma", spec.md).
 */
import { Injectable } from '@nestjs/common';
import { AuditEntityType } from '@prisma/client';

import { AuditRecorder } from '../../../../core/audit/application/audit-recorder.service';
import { EntityCodeGeneratorPort } from '../../../../grc/shared/domain/ports/entity-code-generator.port';
import { UnauthorizedDomainError } from '../../../../shared/errors/domain-error';
import { TransactionRunnerPort } from '../../../../shared/persistence/transaction-runner.port';
import { registerComplianceAuditAllowlists } from '../../domain/compliance-audit-allowlist';
import { ComplianceReferenceDataPort } from '../../domain/ports/compliance-reference-data.port';
import { FrameworkRepositoryPort } from '../../domain/ports/framework-repository.port';

import type { FrameworkRecord } from '../../domain/framework.entity';
import type { FrameworkOrigin } from '@prisma/client';

export interface CreateFrameworkInput {
  readonly actorUserId: string;
  readonly name: string;
  readonly description: string;
  readonly origin: FrameworkOrigin;
}

@Injectable()
export class CreateFrameworkUseCase {
  constructor(
    private readonly transactionRunner: TransactionRunnerPort,
    private readonly frameworkRepository: FrameworkRepositoryPort,
    private readonly codeGenerator: EntityCodeGeneratorPort,
    private readonly referenceData: ComplianceReferenceDataPort,
    private readonly auditRecorder: AuditRecorder,
  ) {
    // Idempotent — see that function's own doc comment.
    registerComplianceAuditAllowlists();
  }

  async execute(input: CreateFrameworkInput): Promise<FrameworkRecord> {
    const actor = await this.referenceData.findUser(input.actorUserId);
    if (!actor) {
      // Defensive only: `SessionGuard` already proved this user has a live
      // session, so the actor row existing is expected. Fails closed
      // rather than attributing an audit event to a fabricated label —
      // mirrors `CreateControlUseCase`'s own identical check.
      throw new UnauthorizedDomainError();
    }

    const codeYear = new Date().getUTCFullYear();

    return this.transactionRunner.run(async () => {
      const code = await this.codeGenerator.nextCode('FMK', codeYear);

      const record = await this.frameworkRepository.create({
        code,
        name: input.name,
        description: input.description,
        origin: input.origin,
      });

      await this.auditRecorder.record({
        action: 'framework.created',
        entityType: AuditEntityType.FRAMEWORK,
        entityId: record.id,
        actorLabel: actor.fullName,
        newValues: {
          name: input.name,
          description: input.description,
          origin: input.origin,
        },
      });

      return record;
    });
  }
}
